import test from 'node:test';
import assert from 'node:assert/strict';
import { doseAdvice, fuelDayScore, weekCompare, weekDeltas, createRecipes, addRecipe, createPantry, addPantryItem, removePantryItem, createStack, toggleIntake, stackProgress, addStackItem, nextDue, weekData, weekSummary } from './fuel-state.js';
test('recipe save validates and lands on top of the library',()=>{const recipes=createRecipes();assert.equal(addRecipe(recipes,{name:'',kcal:500,p:30}),null);assert.equal(addRecipe(recipes,{name:'Lencsés curry',kcal:0,p:20}),null);const saved=addRecipe(recipes,{name:'Lencsés curry',kcal:610,p:31});assert.equal(recipes[0],saved);assert.equal(saved.fit,null);});
test('pantry add and remove keep the shelf honest',()=>{const pantry=createPantry(),count=pantry.length;const item=addPantryItem(pantry,{name:'Túró',kind:'food',amount:'250 g',source:'fotó'});assert.equal(pantry.length,count+1);assert.equal(pantry[0],item);assert.equal(removePantryItem(pantry,item.id),true);assert.equal(pantry.length,count);assert.equal(removePantryItem(pantry,'missing'),false);});
test('intake tick toggles and undo restores the previous state',()=>{const stack=createStack();assert.equal(stackProgress(stack).taken,2);assert.equal(toggleIntake(stack,'s-kreatin'),true);assert.equal(stackProgress(stack).taken,3);assert.equal(toggleIntake(stack,'s-kreatin'),false);assert.equal(stackProgress(stack).taken,2);assert.equal(toggleIntake(stack,'missing'),null);});
test('a new stack item is auto-placed and counted',()=>{const stack=createStack();const item=addStackItem(stack,{name:'Cink',dose:'15 mg',zone:'este',zoneLabel:'Vacsorával'});assert.equal(stack.items.at(-1),item);assert.equal(stackProgress(stack).total,5);assert.equal(addStackItem(stack,{name:''}),null);});
test('week summary counts only logged days and stays honest on gaps',()=>{const s=weekSummary(weekData.current);assert.equal(s.logged,3);assert.equal(s.within,3);assert.ok(Number.isFinite(s.avg));assert.equal(s.weekendDelta,null);const p=weekSummary(weekData.previous);assert.equal(p.logged,7);assert.ok(p.weekendDelta>0);assert.equal(weekSummary({days:[]}).avg,null);});
test('weekday/weekend split and week-over-week deltas ignore unlogged days',()=>{const c=weekCompare(weekData.current);assert.equal(c.coverage,3);assert.equal(c.weekend,null);assert.equal(c.delta,null);const p=weekCompare(weekData.previous);assert.ok(p.weekend>p.weekday);assert.equal(p.delta,p.weekend-p.weekday);const d=weekDeltas(weekData.current,weekData.previous);assert.equal(d.score,.6);assert.equal(d.weight,-.3);});
test('the day fuel score renormalises like the day engine and stays null without data',()=>{const [mon,,wed,thu]=weekData.current.days;assert.equal(fuelDayScore(mon),82);assert.equal(fuelDayScore(wed),81);assert.equal(fuelDayScore(thu),null);assert.equal(fuelDayScore({dims:{nutrition:{score:60},quality:{score:null}}}),60);});
test('the tick records a time, the undo removes it, and the next due follows zone order',()=>{const stack=createStack();assert.equal(nextDue(stack).id,'s-kreatin');assert.equal(toggleIntake(stack,'s-kreatin','12:40'),true);assert.equal(stack.times['s-kreatin'],'12:40');assert.equal(nextDue(stack).id,'s-magnezium');assert.equal(toggleIntake(stack,'s-kreatin'),false);assert.equal(stack.times['s-kreatin'],undefined);toggleIntake(stack,'s-kreatin');toggleIntake(stack,'s-magnezium');assert.equal(nextDue(stack),null);});
test('the dose advisor converts a product label into a daily plan and stays silent on unknowns',()=>{const d3=doseAdvice({name:'D3+K2 2000 NE',perUnit:2000,unitForm:'kapszula',container:90});assert.equal(d3.units,2);assert.equal(d3.daily,4000);assert.equal(d3.days,45);assert.equal(d3.zone,'delben');assert.ok(d3.reason.includes('Zsírban oldódó'));
 const magnesium=doseAdvice({name:'Magnézium-biszglicinát',perUnit:200,container:120,dailyOverride:200});assert.equal(magnesium.units,1);assert.equal(magnesium.days,120);
 assert.equal(doseAdvice({name:'Valami ismeretlen por',perUnit:500}),null);
 assert.equal(doseAdvice({name:'Cink-glükonát'}).unknownProduct,true);});
